CREATE TABLE rule_broker_operation_mechanic(rule_id bigint PRIMARY KEY REFERENCES rule_rule(rule_id));
CREATE TABLE rule_broker_operation(rule_id bigint NOT NULL REFERENCES rule_broker_operation_mechanic(rule_id),operation_code text NOT NULL CHECK(operation_code IN('find-supplier','find-buyer','determine-purchase-price','determine-sale-price')),skill_rule_id bigint NOT NULL REFERENCES rule_skill(rule_id),difficulty_rule_id bigint NOT NULL REFERENCES rule_difficulty(rule_id),time_frame_rule_id bigint NOT NULL REFERENCES rule_time_frame(rule_id),display_order smallint NOT NULL CHECK(display_order>0),PRIMARY KEY(rule_id,operation_code),UNIQUE(rule_id,display_order));
CREATE TABLE rule_carousing_influence_mechanic(rule_id bigint PRIMARY KEY REFERENCES rule_rule(rule_id),skill_rule_id bigint NOT NULL REFERENCES rule_skill(rule_id),influence_system_rule_id bigint NOT NULL REFERENCES rule_attitude_influence_system(rule_id));
COMMENT ON TABLE rule_broker_operation IS 'CE-SKILL-020 paired-source Broker counterparty-search and price-determination operations.';
COMMENT ON TABLE rule_carousing_influence_mechanic IS 'CE-SKILL-021 Carousing as an interaction skill for attitude influence.';
